mapper.select:
WITH res AS ( SELECT c.*, ( SELECT COUNT(*) FROM comments WHERE parent_id = c.id ) AS child_count FROM public.comments c WHERE c.reference_type = CAST(#{referenceType} AS comment_reference_type) AND c.reference_id = #{referenceId} AND c.parent_id IS NULL ORDER BY c.id DESC
LIMIT #{limit}
) SELECT * FROM res ORDER BY id ASC

SELECT EXISTS(
    SELECT 1
    FROM public.comments c
    JOIN auth.users u ON c.users_id = u.id
    WHERE c.id = #{id}
    AND u.email = #{email}
) AS exists;

SELECT COUNT(*)
FROM public.comments c
WHERE c.reference_type = CAST(#{referenceType} AS comment_reference_type)
AND c.reference_id = #{referenceId}
AND c.users_id = (
    SELECT id FROM auth.users u WHERE u.email = #{email}
)
AND c.created_at >= NOW() - INTERVAL '5 minutes';

mapper.update:
UPDATE public.comments
SET details = #{data.details}
WHERE deleted IS FALSE
AND id = #{data.id}
AND users_id = (
    SELECT id FROM auth.users u WHERE u.email = #{email}
)
